let recoveryTimer=null; function scheduleRecovery(){clearTimeout(recoveryTimer);recoveryTimer=setTimeout(()=>{try{localStorage.setItem('astro-ui-designer-recovery',JSON.stringify({savedAt:new Date().toISOString(),project:state.project,doc:state.doc,selectedId:state.selectedId}))}catch{}},350)}
