function log(message){state.logs.unshift({time:now(),message}); if(state.logs.length>200)state.logs.length=200; if(state.bottomTab==='console')renderBottom();}
function owner(){return state.doc.kind==='page'?state.project.pages.find(x=>x.id===state.doc.id):state.project.components.find(x=>x.id===state.doc.id)}
