function permissionMode(){return state.project.editor?.permissionMode||'designer'}
function canEditDomain(node,domain='content'){
  if(permissionMode()==='designer')return node?.meta?.sourceOwnership!=='code';
  if(node?.meta?.sourceOwnership==='code')return false;
  const exposed=node?.meta?.exposed||{};
  if(permissionMode()==='content')return domain==='content'&&exposed.content!==false;
  return Boolean(exposed[domain] ?? (domain==='content'));
}
function applyPermissionClass(){document.body.classList.toggle('mode-client',permissionMode()!=='designer');document.body.dataset.permissionMode=permissionMode()}
function setPermissionMode(mode){if(!['designer','content','client'].includes(mode))return;state.project.editor??={};state.project.editor.permissionMode=mode;applyPermissionClass();renderAll();log(`Permission mode: ${mode}`)}
function currentLocale(){return state.project.editor?.activeLocale||state.project.locales?.default||'en'}

function setEditorView(view){
  state.editorView=view; state.mode=view==='preview'?'preview':'design';
  const area=$('.canvas-area');area.classList.remove('view-code','view-split','view-live');
  if(view==='code')area.classList.add('view-code');else if(view==='split')area.classList.add('view-split');else if(view==='live')area.classList.add('view-live');
  refreshSourcePane();renderCanvas();syncTabButtons();renderStatus();
}
function generatedSourceFiles(){const files=generateAstroProject(state.project);return Object.fromEntries(Object.entries(files).filter(([,v])=>typeof v==='string'))}
function sourceFileEntries(){const workspace=(state.project.workspace?.files||[]).map(f=>({name:f.filename,kind:'workspace',content:f.source||''}));const generated=Object.entries(generatedSourceFiles()).map(([name,content])=>({name,kind:'generated',content}));const seen=new Set();return [...workspace,...generated].filter(x=>!seen.has(x.name)&&seen.add(x.name))}
function refreshSourcePane(){
  const pane=$('#source-pane');if(!pane)return;const list=sourceFileEntries();if(!state.sourceFile||!list.some(x=>x.name===state.sourceFile)){state.sourceFile=state.doc.kind==='page'?`src/pages/${owner()?.filename||'index.astro'}`:state.doc.kind==='component'?`src/components/${owner()?.filename||''}`:list[0]?.name||'';if(!list.some(x=>x.name===state.sourceFile))state.sourceFile=list[0]?.name||'';}
  const sel=$('#source-file-select');if(sel){sel.innerHTML=list.map(x=>`<option value="${htmlEsc(x.name)}" ${x.name===state.sourceFile?'selected':''}>${htmlEsc(x.name)} · ${x.kind}</option>`).join('');sel.onchange=()=>{state.sourceFile=sel.value;refreshSourcePane()}}
  const item=list.find(x=>x.name===state.sourceFile);const editor=$('#source-editor');if(editor&&document.activeElement!==editor)editor.value=item?.content||'';
  const snap=state.project.workspace?.files?.find(f=>f.filename===state.sourceFile);const badge=$('#source-ownership-badge');if(badge)badge.textContent=(snap?.ownership||'generated').toUpperCase();
  if($('#source-reload-btn'))$('#source-reload-btn').onclick=async()=>{if(!snap)return refreshSourcePane();try{const r=await readWorkspaceFile(state.sourceFile);addSourceSnapshot(state.project,state.sourceFile,r.content);refreshSourcePane();log(`Reloaded ${state.sourceFile}`)}catch(e){log(`Reload source failed: ${e.message}`)}};
  if($('#source-sync-btn'))$('#source-sync-btn').onclick=()=>{const snap=state.project.workspace?.files?.find(f=>f.filename===state.sourceFile);if(!snap)return alert('Select a workspace source snapshot first.');const n=selected();const attrs={id:n.meta?.domId||'',class:[`ui-${n.id}`,n.meta?.className||''].filter(Boolean).join(' '),'aria-label':n.meta?.ariaLabel||'',role:n.meta?.role||'',title:n.meta?.title||'',tabindex:n.meta?.tabIndex??''};const text=['text','heading','button','link','badge','label'].includes(n.type)?n.props?.text:null;const patched=patchAstroNodeByUiId(snap.source,n.id,{attributes:attrs,text});if(!patched.changed)return alert(`No safe mapped source change was made (${patched.reason}). Ensure the Astro element has data-ui-id="${n.id}".`);addSourceSnapshot(state.project,state.sourceFile,patched.source);state.dirty=true;const editor=$('#source-editor');if(editor)editor.value=patched.source;log(`Synchronized ${n.name} into ${state.sourceFile}`)};
  if($('#source-apply-btn'))$('#source-apply-btn').onclick=saveSourceEditor;
}
async function saveSourceEditor(){const editor=$('#source-editor');if(!editor||!state.sourceFile)return;const content=editor.value;const snap=addSourceSnapshot(state.project,state.sourceFile,content);snap.modified=true;state.dirty=true;scheduleRecovery();if(state.project.workspace?.rootPath){try{await writeWorkspaceFile(state.sourceFile,content);snap.modified=false;log(`Saved source ${state.sourceFile}`)}catch(e){log(`Source stored in project snapshot; filesystem save failed: ${e.message}`)}}renderLeft();renderRight();}
async function syncWorkspaceScan(scan,{preserveOwnership=false}={}){
  ensureResearchModel(state.project);
  const prior=new Map((state.project.workspace.files||[]).map(f=>[f.filename,f]));
  state.project.workspace.rootPath=scan.rootPath;state.project.workspace.lastScan=scan.scannedAt;state.project.workspace.files=[];state.project.workspace.externalComponents=[];
  for(const item of scan.astro||[]){const r=await readWorkspaceFile(item.relativePath);const old=prior.get(item.relativePath);const snap=addSourceSnapshot(state.project,item.relativePath,r.content);if(preserveOwnership)snap.ownership=old?.ownership||snap.ownership;snap.astAvailable=Boolean(item.astAvailable);snap.kind=item.kind;snap.framework='astro';}
  for(const item of scan.components||[]){
    let snapshot=state.project.workspace.files.find(f=>f.filename===item.relativePath);
    if(!snapshot){try{const r=await readWorkspaceFile(item.relativePath);snapshot={id:`src_${Math.random().toString(36).slice(2)}`,filename:item.relativePath,kind:'component',framework:item.framework||'astro',props:item.props||[],slots:item.slots||[],uiIds:item.uiIds||[],source:r.content,ownership:prior.get(item.relativePath)?.ownership||'hybrid',modified:false};state.project.workspace.files.push(snapshot);}catch{}}
    const symbol=item.symbol||item.name||item.relativePath.split('/').pop().replace(/\.(astro|tsx?|jsx?|vue|svelte)$/i,'');
    const importPath=item.relativePath.startsWith('src/')?`/${item.relativePath}`:item.relativePath;
    registerExternalComponent(state.project,{name:item.name||symbol,symbol,importPath,framework:item.framework||'astro',props:item.props||[],slots:item.slots||[],sourceFile:item.relativePath});
  }
  state.project.workspace.packageJson=scan.packageJson||null;state.project.workspace.astroConfig=scan.astroConfig||'';state.project.workspace.git=Boolean(scan.git);
}
async function openAstroWorkspace(){
  const rootPath=prompt('Path to an existing Astro project folder:',state.project.workspace?.rootPath||'');if(!rootPath)return;
  try{const scan=await openWorkspace(rootPath);await syncWorkspaceScan(scan);state.workspaceApi=true;state.dirty=true;state.leftTab='sources';renderAll();setEditorView('split');log(`Opened Astro workspace: ${scan.rootPath} · ${(scan.components||[]).length} reusable components · ${(scan.astro||[]).length} Astro files`);
  }catch(e){alert(`Workspace open failed: ${e.message}`);log(`Workspace error: ${e.message}`)}
}
async function refreshAstroWorkspace(){
  if(!state.project.workspace?.rootPath)return openAstroWorkspace();
  try{const scan=await rescanWorkspace();await syncWorkspaceScan(scan,{preserveOwnership:true});state.dirty=true;renderAll();log(`Rescanned workspace · ${(scan.components||[]).length} reusable components · ${(scan.astro||[]).length} Astro files`);
  }catch(e){alert(`Workspace rescan failed: ${e.message}`);log(`Workspace rescan failed: ${e.message}`)}
}

async function toggleLivePreview(){
  try{if(state.project.workspace?.preview?.running){await stopPreview();state.project.workspace.preview={url:'',running:false};state.livePreviewUrl='';setEditorView('design');log('Astro dev preview stopped');return;}
    if(!state.project.workspace?.rootPath)return alert('Open an existing Astro workspace first.');const r=await startPreview();state.project.workspace.preview={url:r.url,running:true};state.livePreviewUrl=r.url;const frame=$('#live-preview-frame');if(frame)frame.src=r.url;setTimeout(()=>{if(frame)frame.src=r.url},900);setEditorView('live');log(`Astro dev preview: ${r.url}`);
  }catch(e){alert(`Live preview failed: ${e.message}`);log(`Live preview failed: ${e.message}`)}
}

function insertExternalComponent(descriptorId,parentId=null){const d=state.project.workspace?.externalComponents?.find(x=>x.id===descriptorId);if(!d)return null;const parent=findNode(root(),parentId||state.selectedId);const target=canAcceptChildren(parent)?parent:findParent(root(),state.selectedId);if(!target||!canAcceptChildren(target))return null;const propsObj=Object.fromEntries((d.props||[]).map(p=>[p.name,p.type==='boolean'?false:p.type==='number'?0:p.options?.[0]||'']));const n=createNode('externalComponent',{name:`${d.name}Instance`,props:{descriptorId:d.id,symbol:d.symbol,importPath:d.importPath,framework:d.framework||'astro',client:'none',propsJson:JSON.stringify(propsObj)}});mutate(`Insert external ${d.name}`,()=>{target.children.push(n);state.selectedId=n.id});return n}
function renderSourcesPanel(c){ensureResearchModel(state.project);const files=state.project.workspace.files||[],ext=state.project.workspace.externalComponents||[];c.innerHTML=`<div class="left-actions"><button id="open-workspace-left">Open Astro Project</button><button id="rescan-sources">Refresh</button></div><div class="group-head">Source Workspace</div><div class="research-card"><strong>${htmlEsc(state.project.workspace.rootPath||'No local workspace')}</strong><div class="meta">${files.length} source snapshots · ${ext.length} reusable code components</div></div>${files.map(f=>`<div class="source-row" data-file="${htmlEsc(f.filename)}"><span>${f.kind==='component'?'◇':'▤'}</span><span>${htmlEsc(f.filename)}<br><small>${f.props?.length||0} props · ${f.slots?.length||0} slots · ${htmlEsc(f.ownership||'hybrid')}</small></span><span><button data-open-source="${htmlEsc(f.filename)}">Open</button></span></div>`).join('')||'<div class="empty">Open a real Astro project or import source snapshots.</div>'}<div class="group-head">Code Components</div>${ext.map(d=>`<div class="source-row" data-ext="${d.id}"><span>EX</span><span>${htmlEsc(d.name)}<br><small>${htmlEsc(d.importPath)} · ${(d.props||[]).map(p=>p.name).join(', ')||'no props'}</small></span><span><button data-insert-ext="${d.id}">＋</button></span></div>`).join('')||'<div class="empty">Astro component files are discovered automatically.</div>'}`;
  $('#open-workspace-left').onclick=openAstroWorkspace;$('#rescan-sources').onclick=refreshAstroWorkspace;c.querySelectorAll('[data-open-source]').forEach(b=>b.onclick=()=>{state.sourceFile=b.dataset.openSource;setEditorView('code')});c.querySelectorAll('[data-insert-ext]').forEach(b=>b.onclick=()=>insertExternalComponent(b.dataset.insertExt));}

