  const storyHtml=def ? `<div class="group-head">${htmlEsc(def.name)} stories</div>${(def.stories||[]).map((story,i)=>`<div class="story-row"><span>◇</span><span>${htmlEsc(story.name)}<br><small>${story.viewport}px · ${htmlEsc(story.theme)} · ${htmlEsc(story.locale)}</small></span><button data-del-story="${i}">×</button></div>`).join('') || '<div class="empty">No stories yet.</div>'}` : '';
