function commandPalette(){const layer=$('#modal-layer');layer.innerHTML=`<div class="modal-backdrop"><div class="modal command-palette"><input id="command-search" class="command-search" placeholder="Type a command…"><div id="command-list" class="command-list"></div></div></div>`;const input=$('#command-search'),list=$('#command-list');let matches=[];function draw(){const q=input.value.toLowerCase();matches=COMMANDS.filter(c=>c[0].toLowerCase().includes(q));list.innerHTML=matches.map((c,i)=>`<div class="command-item ${i===0?'active':''}" data-i="${i}"><span>${htmlEsc(c[0])}</span><span class="command-key">${htmlEsc(c[1])}</span></div>`).join('');list.querySelectorAll('.command-item').forEach(x=>x.onclick=()=>run(Number(x.dataset.i)))}function run(i=0){layer.innerHTML='';matches[i]?.[2]?.()}input.oninput=draw;input.onkeydown=e=>{if(e.key==='Enter')run(0);if(e.key==='Escape')layer.innerHTML=''};draw();input.focus()}
