function newProject(){if(state.dirty&&!confirm('Discard unsaved changes and create a new project?'))return;state.project=createProject();ensureResearchModel(state.project);state.doc={kind:'page',id:state.project.pages[0].id};state.selectedId=state.project.pages[0].root.id;state.multiSelected?.clear();state.breakpoint='base';state.mode='design';state.editorView='design';state.sourceFile='';state.livePreviewUrl='';state.gitCache={status:[],diff:''};state.auditCache=[];state.auditWidth=null;state.testRecording=null;state.zoom=1;state.history=[];state.future=[];state.dirty=false;state.bottomExpanded=false;state.focusMode=false;state.focusRestore=null;resetPreviewState();renderAll();setEditorView('design');log('New project created')}
function setMode(m){setEditorView(m==='preview'?'preview':'design')}
function setZoom(z){state.zoom=Math.max(.4,Math.min(1.8,Math.round(z*10)/10));renderCanvas()}


function insertionParent(){let p=selected();if(!canAcceptChildren(p))p=findParent(root(),p.id)||root();return p}
function insertPaletteType(type,parentId=null){const spec=COMPONENTS[type];if(!spec)return null;if(spec.paletteHidden)return null;if(spec.componentDefinitionOnly&&state.doc.kind!=='component'){log(`${spec.label} can only be used inside component definitions.`);return null}let parent=parentId?findNode(root(),parentId):insertionParent();if(!parent||!canAcceptChildren(parent))parent=root();let created=null;mutate(`Insert ${spec.label}`,()=>{created=createNode(type);if(COMPONENTS[parent.type]?.freeformChildren){const offset=24+(parent.children.length%8)*18;created.style.base={...(created.style.base||{}),position:'absolute',left:`${offset}px`,top:`${offset}px`,width:created.style.base?.width||'220px'}}parent.children.push(created);state.multiSelected?.clear();state.selectedId=created.id});return created}
function insertReusableComponent(definitionId,parentId=null){const d=state.project.components.find(x=>x.id===definitionId);if(!d)return null;let parent=parentId?findNode(root(),parentId):insertionParent();if(!parent||!canAcceptChildren(parent))parent=root();let created=null;mutate(`Insert ${d.name}`,()=>{created=createNode('componentInstance',{name:`${d.name}Instance`,props:{definitionId:d.id,propValues:{}}});parent.children.push(created);state.multiSelected?.clear();state.selectedId=created.id});return created}
function selectionNodes(){const ids=new Set(state.multiSelected||[]);if(state.selectedId&&state.selectedId!==root().id)ids.add(state.selectedId);return [...ids].map(id=>findNode(root(),id)).filter(Boolean)}
function freeformSelection(){const nodes=selectionNodes();if(nodes.length<2)return null;const parents=nodes.map(n=>findParent(root(),n.id));if(!parents[0]||parents.some(p=>p?.id!==parents[0].id)||!COMPONENTS[parents[0].type]?.freeformChildren)return null;return {nodes,parent:parents[0]}}
function px(v,fallback=0){const n=parseFloat(String(v??''));return Number.isFinite(n)?n:fallback}
function nodeRectWorld(n){const el=$('#artboard')?.querySelector(`[data-node-id="${CSS.escape(n.id)}"]`);const r=el?.getBoundingClientRect();return {left:px(n.style?.base?.left,r?((r.left-$('#artboard').getBoundingClientRect().left)/state.zoom):0),top:px(n.style?.base?.top,r?((r.top-$('#artboard').getBoundingClientRect().top)/state.zoom):0),width:px(n.style?.base?.width,r?r.width/state.zoom:100),height:px(n.style?.base?.height,r?r.height/state.zoom:40)}}
function alignSelection(mode){const group=freeformSelection();if(!group){log('Align/distribute requires 2+ sibling objects inside a Freeform Layer.');return}const entries=group.nodes.map(n=>({n,r:nodeRectWorld(n)}));mutate(`Align ${mode}`,()=>{if(mode==='left'){const x=Math.min(...entries.map(e=>e.r.left));for(const e of entries)e.n.style.base.left=`${Math.round(x)}px`}if(mode==='right'){const x=Math.max(...entries.map(e=>e.r.left+e.r.width));for(const e of entries)e.n.style.base.left=`${Math.round(x-e.r.width)}px`}if(mode==='hcenter'){const x=entries.reduce((a,e)=>a+e.r.left+e.r.width/2,0)/entries.length;for(const e of entries)e.n.style.base.left=`${Math.round(x-e.r.width/2)}px`}if(mode==='top'){const y=Math.min(...entries.map(e=>e.r.top));for(const e of entries)e.n.style.base.top=`${Math.round(y)}px`}if(mode==='bottom'){const y=Math.max(...entries.map(e=>e.r.top+e.r.height));for(const e of entries)e.n.style.base.top=`${Math.round(y-e.r.height)}px`}if(mode==='vcenter'){const y=entries.reduce((a,e)=>a+e.r.top+e.r.height/2,0)/entries.length;for(const e of entries)e.n.style.base.top=`${Math.round(y-e.r.height/2)}px`}})}
function distributeSelection(axis){const group=freeformSelection();if(!group||group.nodes.length<3){log('Distribution requires 3+ sibling objects inside a Freeform Layer.');return}const entries=group.nodes.map(n=>({n,r:nodeRectWorld(n)})).sort((a,b)=>axis==='h'?a.r.left-b.r.left:a.r.top-b.r.top);mutate(`Distribute ${axis==='h'?'horizontally':'vertically'}`,()=>{if(axis==='h'){const start=entries[0].r.left,end=entries.at(-1).r.left+entries.at(-1).r.width,total=entries.reduce((a,e)=>a+e.r.width,0),gap=(end-start-total)/(entries.length-1);let x=start;for(const e of entries){e.n.style.base.left=`${Math.round(x)}px`;x+=e.r.width+gap}}else{const start=entries[0].r.top,end=entries.at(-1).r.top+entries.at(-1).r.height,total=entries.reduce((a,e)=>a+e.r.height,0),gap=(end-start-total)/(entries.length-1);let y=start;for(const e of entries){e.n.style.base.top=`${Math.round(y)}px`;y+=e.r.height+gap}}})}
function nudgeSelected(dx,dy,resize=false,step=null){const n=selected(),p=findParent(root(),n.id);if(!p||!COMPONENTS[p.type]?.freeformChildren)return false;const g=step??(Number(state.project.settings.gridSize)||8);mutate(resize?'Resize object':'Nudge object',()=>{n.style.base??={};if(resize){const w=Math.max(24,px(n.style.base.width,120)+dx*g),h=Math.max(24,px(n.style.base.height,40)+dy*g);if(dx)n.style.base.width=`${Math.round(w)}px`;if(dy)n.style.base.height=`${Math.round(h)}px`}else{n.style.base.position='absolute';n.style.base.left=`${Math.round(px(n.style.base.left,0)+dx*g)}px`;n.style.base.top=`${Math.round(px(n.style.base.top,0)+dy*g)}px`}});return true}
function moveToEdge(front=true){const n=selected(),p=findParent(root(),n.id);if(!p)return false;const i=p.children.findIndex(x=>x.id===n.id);if(i<0)return false;mutate(front?'Bring to front':'Send to back',()=>{p.children.splice(i,1);front?p.children.push(n):p.children.unshift(n)});return true}
function toggleSelectedMeta(key){const n=selected();mutate(`Toggle ${key}`,()=>{n.meta??={};n.meta[key]=!n.meta[key]})}
function showNodeContextMenu(e,node){e.preventDefault();e.stopPropagation();if(state.mode!=='design')return;state.multiSelected?.clear();state.selectedId=node.id;renderCanvas();renderRight();renderBottom();renderStatus();const actions=[['Cut',cutSelected],['Copy',copySelected],['Paste',pasteSelected],['Duplicate',duplicateSelected],['Delete',deleteSelected],['Wrap in Row',()=>wrapSelected('row')],['Wrap in Column',()=>wrapSelected('column')],['Bring to Front',()=>moveToEdge(true)],['Send to Back',()=>moveToEdge(false)],[node.meta?.locked?'Unlock':'Lock',()=>toggleSelectedMeta('locked')],[node.meta?.hidden?'Show':'Hide',()=>toggleSelectedMeta('hidden')]];const layer=$('#popover-layer');layer.innerHTML=`<div class="menu-popover node-context" style="left:${Math.min(e.clientX,innerWidth-210)}px;top:${Math.min(e.clientY,innerHeight-310)}px">${actions.map((a,i)=>`<button data-i="${i}">${htmlEsc(a[0])}</button>`).join('')}</div>`;layer.querySelectorAll('button').forEach(b=>b.onclick=()=>{layer.innerHTML='';actions[Number(b.dataset.i)][1]()})}
function fitArtboard(){const shell=$('#artboard-shell');if(!shell)return;const available=Math.max(320,shell.clientWidth-64);setZoom(Math.min(1.4,Math.max(.4,available/(bp().width||1280))))}
function setupDockSplitters(){const rootStyle=document.documentElement.style;try{const saved=JSON.parse(localStorage.getItem('astro-ui-dock-layout')||'{}');if(saved.left)rootStyle.setProperty('--left-dock-width',`${saved.left}px`);if(saved.right)rootStyle.setProperty('--right-dock-width',`${saved.right}px`);if(saved.bottom)rootStyle.setProperty('--bottom-dock-height',`${saved.bottom}px`);state.dockHidden.left=Boolean(saved.leftHidden);state.dockHidden.right=Boolean(saved.rightHidden);state.bottomExpanded=Boolean(saved.bottomExpanded)}catch{}applyShellState();const cfg=[['#left-splitter','left'],['#right-splitter','right'],['#bottom-splitter','bottom']];for(const [sel,kind] of cfg){const h=$(sel);if(!h)continue;h.onpointerdown=e=>{e.preventDefault();if(kind==='bottom'&&!state.bottomExpanded)setBottomExpanded(true,{persist:false});h.classList.add('dragging');const sx=e.clientX,sy=e.clientY;const cs=getComputedStyle(document.documentElement);const start=kind==='left'?px(cs.getPropertyValue('--left-dock-width'),235):kind==='right'?px(cs.getPropertyValue('--right-dock-width'),330):px(cs.getPropertyValue('--bottom-dock-height'),170);const move=ev=>{let v=kind==='left'?start+(ev.clientX-sx):kind==='right'?start-(ev.clientX-sx):start-(ev.clientY-sy);v=Math.round(Math.max(kind==='bottom'?110:190,Math.min(kind==='bottom'?520:560,v)));rootStyle.setProperty(kind==='left'?'--left-dock-width':kind==='right'?'--right-dock-width':'--bottom-dock-height',`${v}px`)};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);h.classList.remove('dragging');persistShellLayout()};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)}}setupScrollableTabs()}
